/**
 * Synthetic documents for `proposeDetails` (5.37): passports, licences,
 * insurance policies, bills, statements and letters, UK and US, as a page's
 * own text or OCR gives them, with what a person would fill in for each.
 * Everything here is made up — the people, the numbers, the addresses —
 * and written fresh for the public tests; none of it is any real document.
 *
 * Two sets. TUNED was written with the rules, and the rules were adjusted
 * until they read it. HELD_OUT was written separately, by someone who
 * never saw the rules, from a description of the documents alone; it was
 * first run once the rules were frozen, and never used to change them: it
 * is how the rules do on wording they were not written for. (The
 * description named a few of the vocabularies the 2.6 spike missed, which
 * the rules cover, so it is not wholly independent of them.)
 */
import type { KnownIssuer } from '../issuers.js';
import type { ProposalKind, ProposalPerson } from '../proposals.js';

export interface ProposalFixture {
  name: string;
  text: string;
  /** What a person would fill in; null where the document does not say, or is none of the kinds. */
  truth: {
    type_key: string | null;
    owner: string | null;
    issued: string | null;
    expires: string | null;
    identifier: string | null;
    issued_by: string | null;
  };
}

